INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Netzwerkadresse immer manuell gesetzt werden muss?', 2, '[{"text": "Nein", "correct": true, "because": "DHCP kann automatisch zuweisen"}, {"text": "Ja", "correct": false, "because": "Automatisierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellung definiert das Netzwerksegment eines Geräts?', 3, '[{"text": "Subnetzmaske", "correct": true, "because": "Trennt Netzwerk- und Hostteil"}, {"text": "Gateway", "correct": false, "because": "Nur Routing"}, {"text": "DNS", "correct": false, "because": "Namensauflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Parameter muss ich setzen, um ein Gerät ins Netzwerk einzubinden?', 5, '[{"text": "IP-Adresse", "correct": true, "because": "Identifiziert Gerät"}, {"text": "Subnetzmaske", "correct": true, "because": "Definiert Netzwerk"}, {"text": "Standardgateway", "correct": true, "because": "Leitet Daten"}, {"text": "Büroverschönerung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCP kann Adressen automatisch setzen. b) Manuelle Einstellung ist immer sicherer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht zwingend sicherer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerkgerät konfiguriere?', 4, '[{"text": "IP-Adresse", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzwerk"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jedes Gerät eine feste Adresse braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Dynamische Zuweisung möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einstellbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl erneuert die Netzwerkeinstellungen unter Windows?', 3, '[{"text": "`ipconfig /renew`", "correct": true, "because": "Holt neue DHCP-Adresse"}, {"text": "`ipconfig /release`", "correct": false, "because": "Gibt Adresse frei"}, {"text": "`ipconfig /all`", "correct": false, "because": "Nur Anzeige"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine manuelle Netzwerkeinstellung?', 5, '[{"text": "Kontrolle", "correct": true, "because": "Feste Adressen wählbar"}, {"text": "Keine DHCP-Abhängigkeit", "correct": true, "because": "Unabhängig vom Server"}, {"text": "Vorhersehbare Adressen", "correct": true, "because": "Keine Änderungen"}, {"text": "Schnellere Zuweisung", "correct": false, "because": "Manuell langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) eine Subnetzmaske immer 255.255.255.0 ist und b) DHCP automatisch setzt. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Subnetzmaske variabel"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Gerät ins Netzwerk einzubinden?', 4, '[{"text": "IP-Adresse", "correct": false, "because": "Identifiziert Gerät"}, {"text": "Gateway", "correct": false, "because": "Leitet Daten"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ich immer das Gateway setzen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei externer Kommunikation"}, {"text": "Ja", "correct": false, "because": "Lokale Netze ohne nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken nutze ich, um eine Adresse festzulegen?', 4, '[{"text": "Manuelle Eingabe", "correct": true, "because": "Statische IP"}, {"text": "DHCP", "correct": true, "because": "Dynamische Zuweisung"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine feste Adresse immer sicherer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit unabhängig"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Netzwerkeinstellung?', 3, '[{"text": "Netzwerkkommunikation", "correct": true, "because": "Verbindet Geräte"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Subnetzmaske trennt Netzwerke. b) Gateway ist optional.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Gateway bei lokalen Netzen nicht nötig"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Standardgateway?', 4, '[{"text": "Datenweiterleitung", "correct": true, "because": "Verbindet Netzwerke"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Anderer Zweck"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP immer eine Adresse zuweist?', 2, '[{"text": "Nein", "correct": true, "because": "Server kann ausfallen"}, {"text": "Ja", "correct": false, "because": "Abhängig von Verfügbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Netzwerkeinstellung effektiv?', 5, '[{"text": "Korrekte IP", "correct": true, "because": "Einzigartig im Netzwerk"}, {"text": "Passende Subnetzmaske", "correct": true, "because": "Definiert Bereich"}, {"text": "Gateway bei Bedarf", "correct": true, "because": "Externer Zugriff"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss die Subnetzmaske immer 255.255.255.0 sein?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Netzwerk"}, {"text": "Ja", "correct": false, "because": "Variabel einstellbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Netzwerkeinstellung?', 4, '[{"text": "Statische IP für Server", "correct": true, "because": "Feste Adresse nötig"}, {"text": "Webdesign erstellen", "correct": false, "because": "Anderer Bereich"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}]');
